values ('yangi-oquv-yili-2026', 'Yangi o‘quv yili 2026–2027: birga katta maqsadlar sari', '1-sentabr — bilim bayrami. Bu yil maktabimizda yangi o‘quvchilar, yangi loyihalar va yangi imkoniyatlar bilan kutilmoqda.', '[{"type":"h","text":"Bayram tongi"},{"type":"p","text":"202-maktab hovlisida 1-sentabr tongi yana bir bor bilim bayramiga aylandi. Birinchi sinf o‘quvchilarini katta hurmat bilan kutib olishdik — ustozlar va katta o‘quvchilar ularni gulchambarlar bilan kutib oldi."},{"type":"quote","text":"Har bir o‘quv yili — yangi sahifa. Biz u sahifalarga birgalikda yozamiz."},{"type":"h","text":"Yangi loyihalar"},{"type":"p","text":"Yangi o‘quv yilida fan to‘garaklari, sport musobaqalari va ijodiy loyihalar yanada kengayadi. Ota-onalar uchun axborot uchrashuvlari jadvali maktab kanalida e’lon qilinadi."},{"type":"p","text":"Barcha o‘quvchi, ustoz va ota-onalarga sog‘lom, omadli va barakali o‘quv yili tilaymiz!"}]'::jsonb, '/images/hero.jpg', 'Maktab binosi bayram kuni', 'Yangiliklar', (select id from news_categories where name = 'Yangiliklar'), null, '3 daqiqa', true, '2026-09-01T06:00:00Z'::timestamptz)
on conflict (slug) do nothing;
values ('ota-onalar-uchun-ochiq-eshiklar-kuni', 'Ota-onalar uchun ochiq eshiklar kuni', 'Sentabr oyi davomida ota-onalar maktabga tashrif buyurib, sinfxonalar bilan tanishishi va ustozlar bilan uchrashishi mumkin.', '[{"type":"p","text":"Ochiq eshiklar kuni — ota-onalar uchun maktab hayotini ichidan ko‘rish imkoniyati. Tashrif davomida sinfxonalar, sport zali va kutubxona bilan tanishasiz."},{"type":"p","text":"Aniq sana va vaqt maktab rasmiy kanallarida e’lon qilinadi. Keling, birgalikda o‘quvchilarimiz kelajagini quramiz."}]'::jsonb, '/images/news-open-door.jpg', 'Ota-onalar maktab koridorida', 'Tadbirlar', (select id from news_categories where name = 'Tadbirlar'), null, '2 daqiqa', true, '2026-09-18T06:00:00Z'::timestamptz)
on conflict (slug) do nothing;
values ('fan-olimpiadalari-bosqichi', 'Fan olimpiadalarining tuman bosqichi boshlanmoqda', 'Matematika, fizika va ona tili fani olimpiadalari uchun maktab bosqichi yakunlandi. G‘oliblar tuman bosqichiga yo‘l oldi.', '[{"type":"p","text":"Maktab bosqichida yuzlab o‘quvchilar qatnashdi. Eng yaxshi natijalarni ko‘rsatgan o‘quvchilar tuman bosqichida maktabimiz sharafini himoya qiladi."},{"type":"quote","text":"Olimpiada — bu faqat musobaqa emas, bu intellektual bayram."},{"type":"p","text":"Barcha qatnashchilarga omad tilaymiz!"}]'::jsonb, '/images/news-olympiad.jpg', 'Olimpiada medallari', 'Tanlovlar', (select id from news_categories where name = 'Tanlovlar'), null, '2 daqiqa', true, '2026-09-24T06:00:00Z'::timestamptz)
on conflict (slug) do nothing;
values ('robototexnika-togarak-qabul', 'Robototexnika va STEM to‘garaklariga qabul boshlandi', 'Boshlang‘ich va o‘rta sinf o‘quvchilari uchun yangi STEM to‘garaklari ochiladi. Joylar soni cheklangan.', '[{"type":"p","text":"STEM ta’limi — muhandislik va texnologiyaga qiziqqan bolalar uchun birinchi qadam. To‘garakda o‘quvchilar oddiy robotlar yasashni va dasturlash asoslarini o‘rganadi."},{"type":"p","text":"Ro‘yxatdan o‘tish uchun sinf rahbaringizga murojaat qiling."}]'::jsonb, '/images/news-stem.jpg', 'Robototexnika to''garagi jihozlari', 'Yangiliklar', (select id from news_categories where name = 'Yangiliklar'), null, '2 daqiqa', true, '2026-10-02T06:00:00Z'::timestamptz)
on conflict (slug) do nothing;
values ('maktab-spogatki-yakuni', 'Maktab sporti: kuzgi spartakiada yakunlandi', 'Futbol, voleybol va shaxmat bo‘yicha sinflar o‘rtasidagi musobaqalar muhim natijalar bilan yakunlandi.', '[{"type":"p","text":"Kuzgi spartakiada ikki hafta davom etdi. Barcha sinflar faol qatnashdi — maydonda do‘stlik va kurash ruhi qaynadi."},{"type":"p","text":"G‘olib sinflar maktab qiroysida taqdirlandi. Barcha ishtirokchilarga rahmat!"}]'::jsonb, '/images/life-sport.jpg', 'Maktab maydonchasida futbol', 'Sport', (select id from news_categories where name = 'Sport'), null, '3 daqiqa', true, '2026-10-15T06:00:00Z'::timestamptz)
on conflict (slug) do nothing;
values ('ochiq-darslar-haftaligi', 'Ochiq darslar haftaligi: ustozlar tajribasi ulashmoqda', 'Maktabimizda ochiq darslar haftaligi o‘tkaziladi — ota-onalar va kollega ustozlar darslarni kuzatishi mumkin.', '[{"type":"p","text":"Ochiq darslar — pedagogik mahoratni oshirish va shaffoflik uchun muhim an’ana. Bu haftada bir nechta ustozlar darslarini ochiq o‘tadi."},{"type":"p","text":"Qatnashish uchun oldindan ro‘yxatdan o‘tish talab etiladi."}]'::jsonb, '/images/edu-quality.jpg', 'Ochiq dars jarayoni', 'Ochiq darslar', (select id from news_categories where name = 'Ochiq darslar'), null, '2 daqiqa', true, '2026-11-05T06:00:00Z'::timestamptz)
on conflict (slug) do nothing;

-- ============================================================================
-- TEKSHIRUV — quyidagi hisobot SQL Editor'da natija sifatida chiqadi:
-- ============================================================================
select 'jadval (public sxema)' as narsa, count(*)::text as soni from information_schema.tables where table_schema = 'public'
union all select 'site_settings', count(*)::text from site_settings
union all select 'contact_information', count(*)::text from contact_information
union all select 'news_categories', count(*)::text from news_categories
union all select 'gallery_categories', count(*)::text from gallery_categories
union all select 'statistics', count(*)::text from statistics
union all select 'features', count(*)::text from features
union all select 'facilities', count(*)::text from facilities
union all select 'team_members', count(*)::text from team_members
union all select 'gallery_items', count(*)::text from gallery_items
union all select 'quick_links', count(*)::text from quick_links
union all select 'faqs', count(*)::text from faqs
union all select 'news_articles (published)', count(*)::text from news_articles where is_published
union all select 'rls yoqilgan jadvallar', count(*)::text from pg_tables where schemaname = 'public' and rowsecurity
order by narsa;

