insert into features (id, display_index, title, description, icon, image_url, alt, sort_order, is_visible) values ('quality', '01', 'Sifatli ta’lim', 'Davlat standartiga asoslangan, ammo har bir o‘quvchining qiziqishi va temposiga moslashadigan dars tizimi.', 'book', null, null, 0, true) on conflict (id) do nothing;
insert into features (id, display_index, title, description, icon, image_url, alt, sort_order, is_visible) values ('classrooms', '02', 'Zamonaviy sinfxonalar', 'Yorug‘, shinam sinfxonalar, interaktiv uskunalar va fan kabinetlari — qulay muhitda chuqur o‘zlashtirish uchun.', 'monitor', '/images/edu-classroom.jpg', 'Zamonaviy sinfxona interyeri', 1, true) on conflict (id) do nothing;
insert into features (id, display_index, title, description, icon, image_url, alt, sort_order, is_visible) values ('sport', '03', 'Sport va rivojlanish', 'Sport zali, ochiq maydon va to‘garaklar — sog‘lom tanada sog‘lom aql tamoyili asosida jismoniy tarbiya.', 'ball', '/images/edu-sport.jpg', 'Maktab sport zali', 2, true) on conflict (id) do nothing;
insert into features (id, display_index, title, description, icon, image_url, alt, sort_order, is_visible) values ('library', '04', 'Kutubxona', 'O‘quv adabiyotlari, badiiy kitoblar va o‘quv zallari — mustaqil o‘qish va tadqiqot ko‘nikmalarini shakllantirish uchun.', 'library', '/images/edu-library.jpg', 'Maktab kutubxonasi', 3, true) on conflict (id) do nothing;
insert into features (id, display_index, title, description, icon, image_url, alt, sort_order, is_visible) values ('inclusive', '05', 'Inklyuziv ta’lim', 'Maxsus ehtiyojli o‘quvchilar uchun moslashtirilgan dasturlar, resurslar va malakali mutaxassislar yordami.', 'heart', '/images/edu-inclusive.jpg', 'Inklyuziv ta''lim xonasi', 4, true) on conflict (id) do nothing;
insert into features (id, display_index, title, description, icon, image_url, alt, sort_order, is_visible) values ('events', '06', 'Tadbirlar va maktab hayoti', 'Bayramlar, tanlovlar, olimpiadalar va ijodiy kechalar — o‘quvchilar o‘z qobiliyatlarini namoyish etadigan maydon.', 'star', '/images/edu-events.jpg', 'Maktab akt zali', 5, true) on conflict (id) do nothing;
insert into facilities (id, kicker, title, description, image_url, image_alt, sort_order, is_visible) values ('classrooms', '01 — O‘quv xonalari', 'Yorug‘ sinfxonalar', 'Katta oynalar, qulay mebel va interaktiv taxtalar — darsda e’tibor uzoq saqlanadigan muhit. Har bir kabinet fan talabiga mos jihozlangan.', '/images/edu-classroom.jpg', 'Yorug‘ zamonaviy sinfxona', 0, true) on conflict (id) do nothing;
insert into facilities (id, kicker, title, description, image_url, image_alt, sort_order, is_visible) values ('sport-hall', '02 — Sport inshooti', 'Sport zali va maydon', 'Voleybol va basketbol uchun jihozlangan zal, ochiq futbol maydoni va jismoniy tarbiya to‘garaklari — har kuni faol harakat uchun sharoit.', '/images/edu-sport.jpg', 'Sport zali', 1, true) on conflict (id) do nothing;
insert into facilities (id, kicker, title, description, image_url, image_alt, sort_order, is_visible) values ('assembly', '03 — Akt zali', 'Katta sahna zali', 'Bayramlar, anjumanlar va ijodiy kechalar o‘tkaziladigan keng zal. O‘quvchilar sahnada o‘zini erkin his qiladi va jamoa oldida gapirishni o‘rganadi.', '/images/edu-events.jpg', 'Akt zali', 2, true) on conflict (id) do nothing;
insert into facilities (id, kicker, title, description, image_url, image_alt, sort_order, is_visible) values ('library', '04 — Kutubxona', 'O‘quv va kitob zallari', 'Darsliklar, badiiy adabiyot va o‘quvchilar uchun tinch o‘qish burchaklari. Mustaqil ta’lim olish uchun birinchi manzil.', '/images/edu-library.jpg', 'Kutubxona zali', 3, true) on conflict (id) do nothing;
insert into facilities (id, kicker, title, description, image_url, image_alt, sort_order, is_visible) values ('inclusive-rooms', '05 — Inklyuziv xonalar', 'Qo‘llab-quvvatlash xonalari', 'Maxsus ehtiyojli o‘quvchilar bilan individual va kichik guruhlarda ishlash uchun moslashtirilgan, tinch va mehribon muhit.', '/images/edu-inclusive.jpg', 'Inklyuziv ta''lim xonasi', 4, true) on conflict (id) do nothing;
