insert into faqs (question, answer, sort_order, is_visible) select 'Maktabga qanday qabul qilinadi?', 'Qabul har yili yoz oylarida o‘tkaziladi. Hujjatlar ro‘yxati, smena va sinf to‘ldirilganligi haqida aniq ma’lumotni maktab ma’muriyati yoki aloqa bo‘limidan olishingiz mumkin. Saytdagi aloqa formasi orqali ham murojaat qilishingiz mumkin.', 0, true where not exists (select 1 from faqs where question = 'Maktabga qanday qabul qilinadi?');
insert into faqs (question, answer, sort_order, is_visible) select 'Darslar nechchi smenada o‘tiladi?', 'Smenalar jadvali har o‘quv yilida sinflar soniga qarab shakllantiriladi. Aniq jadvalni sinf rahbari yoki maktab ma’muriyati beradi.', 1, true where not exists (select 1 from faqs where question = 'Darslar nechchi smenada o‘tiladi?');
insert into faqs (question, answer, sort_order, is_visible) select 'Maktabda to‘garaklar bormi?', 'Ha. Sport, ijod, til va texnik yo‘nalishdagi to‘garaklar faoliyat yuritadi. To‘garaklar ro‘yxati va qabul shartlari «Ta’lim» sahifasida e’lon qilinadi.', 2, true where not exists (select 1 from faqs where question = 'Maktabda to‘garaklar bormi?');
insert into faqs (question, answer, sort_order, is_visible) select 'Inklyuziv ta’lim qanday tashkil etilgan?', 'Maxsus ehtiyojli o‘quvchilar uchun moslashtirilgan dasturlar, qo‘llab-quvvatlash xonalari va malakali murabbiylar mavjud. Har bir holat individual o‘rganiladi.', 3, true where not exists (select 1 from faqs where question = 'Inklyuziv ta’lim qanday tashkil etilgan?');
insert into faqs (question, answer, sort_order, is_visible) select 'Ota-onalar maktab hayotida qanday qatnashadi?', 'Ota-onalar qo‘mitasi, ochiq eshiklar kunlari va muntazam uchrashuvlar orqali maktab hayotida faol ishtirok etadi. Barcha tadbirlar yangiliklar bo‘limida e’lon qilinadi.', 4, true where not exists (select 1 from faqs where question = 'Ota-onalar maktab hayotida qanday qatnashadi?');
